        /// <summary>
        /// Size cap of a category: its own, else the nearest parent's, else a sanity default — 24 m for any
        /// leisure/furniture category, 40 m for work sites (future types inherit a cap without listing one).
        /// Nets, fences, surfaces, areas, zones, decals and functional road objects have no cap.
        /// </summary>
        public static float MaxFootprint(string category)
        {
            if (string.IsNullOrEmpty(category)) return 0f;
            // s21: decal pools are capped by what fits their hosts (Core/Decals/DecalPools).
            float decal = Decals.DecalPools.MaxFootprint(category);
            if (decal > 0f) return decal;
            if (MaxSize.TryGetValue(category, out var m)) return m;
            if (category.StartsWith("play.", StringComparison.Ordinal)) return 10f;
            if (category.StartsWith("beach.", StringComparison.Ordinal)) return 10f;
            int dot = category.LastIndexOf('.');
            if (dot > 0 && MaxSize.TryGetValue(category.Substring(0, dot), out m)) return m;
            if (category == AssetCategories.Fence || category == AssetCategories.Pathway || category == AssetCategories.Road
                || category == AssetCategories.InvisiblePath || category == AssetCategories.SurfaceAny || category == AssetCategories.Zone
                || category == AssetCategories.Decal || category == AssetCategories.ParkingDecal || category == AssetCategories.Charger)
                return 0f;
            foreach (var p in NoCapPrefixes)
                if (category.StartsWith(p, StringComparison.Ordinal)) return 0f;
            return IsLeisureCategory(category) ? 24f : 40f;
        }

        private static readonly string[] NoCapPrefixes = { "net.", "surface", "area.", "zone", "decal.", "object.", "parking." };

        /// <summary>False when a known footprint is implausibly big for the category (giant bounds, buildings).</summary>
        public static bool FitsSize(string category, float footprint)
        {
            float max = MaxFootprint(category);
            float min = Decals.DecalPools.MinFootprint(category);
            if (min > 0f && footprint > 0f && footprint < min) return false;
            return max <= 0f || footprint <= 0f || footprint <= max;
        }

        // ───────────────────────── palettes ─────────────────────────

        /// <summary>
        /// A vanilla park palette suitable for dressing an ordinary park: a park/garden/plaza/playground
        /// asset that is not a themed facility. Sports grounds, campfire sites, landmarks, hotels and
        /// overpasses brought floodlights, campground benches and driveway lights into ordinary parks.
        /// </summary>
        public static bool IsGeneralParkPalette(string paletteOrParkName)
        {
            if (string.IsNullOrEmpty(paletteOrParkName)) return false;
            var lower = paletteOrParkName.ToLowerInvariant();
            if (!AssetHeuristics.ContainsAny(lower, "park", "garden", "plaza", "playground")) return false;
            return !AssetHeuristics.ContainsAny(lower, "sport", "skate", "dog", "gym", "water", "school", "university", "college",
                "stadium", "arena", "zoo", "farm", "cemetery", "golf", "beach", "marina", "harbor", "harbour", "landmark",
                "football", "basketball", "baseball", "tennis", "bicycle", "bike", "pool", "campfire", "camp", "ruins", "theatre",
                "theater", "parking", "overpass", "hotel", "castle", "museum", "statue", "tower", "ferris", "maintenance", "depot");
        }
    }
